);
report = report.replace("{{VI_1}}", pdfLines[3]).replace("{{VI_2}}", pdfLines[4]);
if (report.includes("{{")) throw new Error("unfilled placeholder");
const reportPath = "audits/content-search/audit-narrative.md";
await writeFile(path.join(root, reportPath), report);
const reportLines = report.split(/\r?\n/);
const spec = [
  ["render-source-main", "html", 1, '<main id="task">Open Billing. Select Disable renewal.</main>'],
  ["render-source-script", "html", 1, "document.getElementById('task').textContent = 'Open Billing.';"],
  ["rendered-dom-ready", "dom", 1, 'data-audit-ready="true"'],
  ["rendered-dom-main", "dom", 1, '<main id="task">Open Billing.</main>'],
  ["pdf-en-limit", "pdf", 2, "A single export contains at most 5000 records."],
  ["pdf-en-scope", "pdf", 3, "Applies to current VN plans."],
  ["pdf-vi-limit", "pdf", 4, pdfLines[3]],
  ["pdf-vi-charge", "pdf", 5, pdfLines[4]],
];
const quotes = spec.map(([quoteId, key, line, quote]) => {
  const label = path.posix.basename(rel[key]);
  const citation = label + ":" + line;
  const index = reportLines.findIndex((l) => l.includes(citation) && l.includes(quote));
  if (index < 0) throw new Error("report line not found for " + quoteId);
  return {
    quoteId,
    source: rel[key],
    sourceLabel: label,
    sourceHash: sha(bytes[key]),
    startLine: line,
    endLine: line,
    reportStartLine: index + 1,
    reportEndLine: index + 1,
    normalization: "exact",
    quote,
  };
});
const ledger = { root, report: reportPath, reportHash: sha(Buffer.from(report, "utf8")), quotes };
await writeFile(
  path.join(root, "audits/content-search/quote-ledger.json"),
  JSON.stringify(ledger, null, 2) + "\n",
);
